const Imap = require('imap');
const { simpleParser } = require('mailparser');

/**
 * Получение непрочитанных писем
 * @param {string} imap_host - IMAP хост
 * @param {number|string} imap_port - IMAP порт
 * @param {string} imap_user - Логин
 * @param {string} imap_pass - Пароль
 * @param {Object} options - Доп. параметры
 * @param {number|null} [options.days=1] - Кол-во дней назад (null или 0 = отключить фильтр по дате)
 * @param {string} [options.folder='INBOX'] - Папка IMAP
 */
function fetchUnread(imap_host, imap_port, imap_user, imap_pass, options = {}) {
    const { days = 14, folder = 'Рассылки|Прогрев' } = options;

    return new Promise((resolve, reject) => {
        const results = [];
        const imap = new Imap({
            user: imap_user,
            password: imap_pass,
            host: imap_host,
            port: parseInt(imap_port),
            tls: true
        });

        imap.once('ready', function () {
            imap.openBox(folder, false, function (err, box) {
                if (err) return reject(err);

                let searchCriteria = ['UNSEEN'];

                let sinceDate = null;
                if (days && days > 0) {
                    const date = new Date();
                    date.setDate(date.getDate() - days);

                    sinceDate = date;
                    const imapDate = date.toLocaleString('en-US', {
                        day: '2-digit',
                        month: 'short',
                        year: 'numeric'
                    }).replace(',', '');

                    searchCriteria.push(['SINCE', imapDate]);
                }

                imap.search(searchCriteria, function (err, uids) {
                    if (err) return reject(err);
                    if (!uids.length) {
                        imap.end();
                        return resolve([]);
                    }

                    const f = imap.fetch(uids, { bodies: '' });
                    let idCounter = 1;

                    f.on('message', function (msg) {
                        let buffer = '';
                        let uid;

                        msg.on('attributes', attrs => {
                            uid = attrs.uid;
                        });

                        msg.on('body', function (stream) {
                            stream.on('data', function (chunk) {
                                buffer += chunk.toString('utf8');
                            });
                        });

                        msg.once('end', async function () {
                            try {
                                const parsed = await simpleParser(buffer);

                                // если включён фильтр по дате — проверяем ещё раз
                                if (!sinceDate || (parsed.date && parsed.date >= sinceDate)) {
                                    results.push({
                                        id: idCounter++,
                                        sender: parsed.from?.value?.[0]?.address || '',
                                        recipient: parsed.to?.value?.[0]?.address || '',
                                        message_id: parsed.messageId || '',
                                        references: [].concat(parsed.references || []).join(', '),
                                        date: parsed.date ? parsed.date.toString() : '',
                                        folder: folder,
                                        uid: uid,
                                        subject: parsed.subject || '',
                                        textPlain: parsed.text || '',
                                        textHtml: parsed.html || '',
                                        body: parsed.text || parsed.html || ''
                                    });
                                }
                            } catch (e) {
                                reject(e);
                            }
                        });
                    });

                    f.once('error', err => reject(err));
                    f.once('end', function () {
                        imap.end();
                        resolve(results);
                    });
                });
            });
        });

        imap.once('error', err => reject(err));
        imap.once('end', function () {});

        imap.connect();
    });
}

